/**
 * Unit tests for the UserUseSecondFactorsAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserUseSecondFactorsAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that isUseSecondFactors returns null on a freshly created holder.
         */
        public function testUseSecondFactorsNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithUserUseSecondFactorsAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isUseSecondFactorsAssigned());
            $this->assertNull($holder->isUseSecondFactors());
        }
}
